mapper.select:
SELECT DISTINCT p.*
FROM policy p,
     pc.code AS categoryCode,
     pc.name AS categoryName
         JOIN policy_target_region ptr
              ON p.id = ptr.policy_id
         LEFT JOIN policy_category pc
                   ON p.category_id = pc.id
WHERE p.id = #{id}
  AND ptr.sgg_code = #{region}
  AND (
      (p.min_age = 0 AND p.max_age = 0)
      OR (
          p.min_age  <=  #{age}
          AND p.max_age  >=  #{age}
      )
  )

mapper.update:
UPDATE policy_category

SET embedding = #{embedding}

WHERE id = #{id}

UPDATE policy

SET embedding = #{embedding}

WHERE id = #{id}

UPDATE policy

SET
    category_id = #{categoryId},
    category_similarity = #{categorySimilarity}

WHERE id = #{id}
